class Solution {
public:
    int numSubmatrixSumTarget(vector<vector<int>>& matrix, int target) {
        int R = matrix.size(), C = matrix[0].size();
        for (int r = 0; r < R; ++r) {
            for (int c = 1; c < C; ++c) {
                matrix[r][c] += matrix[r][c - 1];
            }
        }

        int res = 0;
        for (int c1 = 0; c1 < C; ++c1) {
            for (int c2 = c1; c2 < C; ++c2) {
                unordered_map<int, int> counts;
                counts[0] = 1;
                int cur = 0;
                for (int r = 0; r < R; ++r) {
                    int row_sum = matrix[r][c2] - (c1 > 0 ? matrix[r][c1 - 1] : 0);
                    cur += row_sum;
                    if (counts.find(cur - target) != counts.end()) {
                        res += counts[cur - target];
                    }
                    counts[cur]++;
                }
            }
        }
        return res;
    }
};

class Solution {
    public int numSubmatrixSumTarget(int[][] matrix, int target) {
        int R = matrix.length, C = matrix[0].length;
        for (int r = 0; r < R; ++r) {
            for (int c = 1; c < C; ++c) {
                matrix[r][c] += matrix[r][c - 1];
            }
        }

        int res = 0;
        for (int c1 = 0; c1 < C; ++c1) {
            for (int c2 = c1; c2 < C; ++c2) {
                Map<Integer, Integer> counts = new HashMap<>();
                counts.put(0, 1);
                int cur = 0;
                for (int r = 0; r < R; ++r) {
                    int rowSum = matrix[r][c2] - (c1 > 0 ? matrix[r][c1 - 1] : 0);
                    cur += rowSum;
                    res += counts.getOrDefault(cur - target, 0);
                    counts.put(cur, counts.getOrDefault(cur, 0) + 1);
                }
            }
        }
        return res;
    }
}

